/**
 * Run several statements atomically in one transaction
 *
 * Runs the supplied statements in a single transaction (the console structure editor's SQLite 12-step table rebuild: create → copy → drop → rename). A failure in any statement rolls the whole batch back, so the table is never left half-migrated. DDL only — no bind parameters.
 *
 */
export const execDataScript = <ThrowOnError extends boolean = false>(options: Options<ExecDataScriptData, ThrowOnError>): RequestResult<ExecDataScriptResponses, ExecDataScriptErrors, ThrowOnError> => (options.client ?? client).post<ExecDataScriptResponses, ExecDataScriptErrors, ThrowOnError>({
    url: '/projects/{name}/data/{source}/script',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

