/**
 * Regenerate the generated TypeScript domain types from the live schema
 *
 * Reifies the datasource schema into `.nanobpm/domain.d.ts` (ADR 0029 §4.1/§6): one `interface` per table plus a `DomainTables` lookup, so workers type against the current tables. Also runs automatically after a schema change (script/DDL exec/migrate) and at App boot; this endpoint is the maker's explicit "regenerate now" affordance. Types are erased at `deno compile` — this is an authoring-time convenience only.
 *
 */
export const regenerateDomainTypes = <ThrowOnError extends boolean = false>(options: Options<RegenerateDomainTypesData, ThrowOnError>): RequestResult<RegenerateDomainTypesResponses, RegenerateDomainTypesErrors, ThrowOnError> => (options.client ?? client).post<RegenerateDomainTypesResponses, RegenerateDomainTypesErrors, ThrowOnError>({ url: '/projects/{name}/data/{source}/domaintypes', ...options });

/**
 * Resolve the in-editor composed shapes for a live preview (no domain-type output written)
 *
 * The authoring-time counterpart to `regenerateDomainTypes` (ADR 0040 §9/§10): resolve the composed motion-shapes the modeller is *currently editing* — sent in the request body, not scanned from the saved `.bpmn` — against the live datasource + manifest-type fuse, and return the emitted domain text plus the per-shape diagnostics. Runs with `write:false`, so it does not materialise the `domaintypes` outputs (`domain-rows.d.ts` and the worker/message bindings): it powers the shape composer's live field preview and inline diagnostics without regenerating the typed SDK the maker consumes. (Like every project op it does ensure the generated SDK *scaffolding* exists, so the first call may seed the `nano-generated/` helpers.)
 *
 */
export const previewDomainTypes = <ThrowOnError extends boolean = false>(options: Options<PreviewDomainTypesData, ThrowOnError>): RequestResult<PreviewDomainTypesResponses, PreviewDomainTypesErrors, ThrowOnError> => (options.client ?? client).post<PreviewDomainTypesResponses, PreviewDomainTypesErrors, ThrowOnError>({
    url: '/projects/{name}/data/{source}/domaintypes/preview',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Nano server version and self-update availability
 *
 * Reports the running server version, the latest available version for the channel this binary was launched from, and whether the launcher can self-update. Self-managed / dev binaries (a configured binary path, a --binary flag, or a repo build) report canSelfUpdate=false and suppress the update nag (updateAvailable=false) even when a newer version exists. Best-effort and offline-soft: version resolution failures degrade to a null latest rather than an error.
 *
 */
export const getServerUpdate = <ThrowOnError extends boolean = false>(options?: Options<GetServerUpdateData, ThrowOnError>): RequestResult<GetServerUpdateResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetServerUpdateResponses, unknown, ThrowOnError>({ url: '/server/update', ...options });

/**
 * Installed extensions overview
 */
export const getExtensions = <ThrowOnError extends boolean = false>(options?: Options<GetExtensionsData, ThrowOnError>): RequestResult<GetExtensionsResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetExtensionsResponses, unknown, ThrowOnError>({ url: '/extensions', ...options });

/**
 * Marketplace of installable extension packs
 *
 * Lists packs on npm tagged `nano-ide-ext`, with installed status and an update-available flag per installed pack. The result is cached server-side for several minutes (computing it shells out to npm once per installed pack), and concurrent callers share one in-flight computation. Pass `refresh=true` for an explicit "check now" that bypasses the cache TTL — it still joins the single in-flight computation, so it never fans a second npm burst out on top of an in-progress one.
 *
 */
export const getMarketplace = <ThrowOnError extends boolean = false>(options?: Options<GetMarketplaceData, ThrowOnError>): RequestResult<GetMarketplaceResponses, unknown, ThrowOnError> => (options?.client ?? client).get<GetMarketplaceResponses, unknown, ThrowOnError>({ url: '/extensions/marketplace', ...options });

/**
 * README (markdown) for an extension pack
 *
 * Returns the pack's README as raw markdown. For an installed pack this is read from the bundled `README.md`; otherwise it is fetched from npm (`npm view <pkg> readme`). Used by the marketplace to show pack detail.
 *
 */
export const getExtensionReadme = <ThrowOnError extends boolean = false>(options: Options<GetExtensionReadmeData, ThrowOnError>): RequestResult<GetExtensionReadmeResponses, GetExtensionReadmeErrors, ThrowOnError> => (options.client ?? client).get<GetExtensionReadmeResponses, GetExtensionReadmeErrors, ThrowOnError>({ url: '/extensions/readme', ...options });

/**
 * Changelog (markdown) for an extension pack
 *
 * Returns the pack's changelog as raw markdown so the marketplace/update panel can show *what changed*. For an installed pack this is read from the bundled `CHANGELOG.md`; otherwise the published registry tarball is downloaded (`npm pack <pkg>@<to>`) and its changelog read — npm does not expose `changelog` via `npm view` the way it does `readme`. When `from` (the installed version) is supplied and the changelog's version headings parse, the result is scoped to the delta between `from` and the latest version, falling back to the full changelog otherwise.
 *
 */
export const getExtensionChangelog = <ThrowOnError extends boolean = false>(options: Options<GetExtensionChangelogData, ThrowOnError>): RequestResult<GetExtensionChangelogResponses, GetExtensionChangelogErrors, ThrowOnError> => (options.client ?? client).get<GetExtensionChangelogResponses, GetExtensionChangelogErrors, ThrowOnError>({ url: '/extensions/changelog', ...options });

