/**
 * Ensure the Urban toolkit (urban CLI + create-urban-app) is present
 *
 * Install-before-create hook (issue #520). Idempotently ensures the first-party `nano-ide-app-urban` marketplace pack and its runtime dependencies (`@nanobpm/urban`, which provides the `urban` CLI, and `create-urban-app`, the scaffolder the console delegates to) are installed, so the Studio can scaffold an Urban app. Cheap no-op when the `urban` CLI already resolves. Returns whether it resolves after the call.
 *
 */
export const installUrbanToolkit = <ThrowOnError extends boolean = false>(options?: Options<InstallUrbanToolkitData, ThrowOnError>): RequestResult<InstallUrbanToolkitResponses, InstallUrbanToolkitErrors, ThrowOnError> => (options?.client ?? client).post<InstallUrbanToolkitResponses, InstallUrbanToolkitErrors, ThrowOnError>({ url: '/urban/install', ...options });

/**
 * Approve or revoke trust for extension toolchains
 */
export const trustExtension = <ThrowOnError extends boolean = false>(options: Options<TrustExtensionData, ThrowOnError>): RequestResult<TrustExtensionResponses, unknown, ThrowOnError> => (options.client ?? client).post<TrustExtensionResponses, unknown, ThrowOnError>({
    url: '/extensions/trust',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Configured triggers + resolved source registry (ADR 0025 phase 2)
 *
 * Lists the App manifest's declared triggers, each resolved against the source registry — the union of the compiled-in core kinds (cron/webhook/file/manual) and every installed pack's declared source kinds (`nano-ide-trigger-*`, ADR 0025 §6). `builtin` says whether the kind runs in-process (core) or is driven by a pack/ingress. Also returns the full registry so the console can offer a source picker, and any config errors (e.g. a malformed cron spec). This is the data the phase-3 Triggers panel renders.
 *
 */
export const getTriggers = <ThrowOnError extends boolean = false>(options: Options<GetTriggersData, ThrowOnError>): RequestResult<GetTriggersResponses, GetTriggersErrors, ThrowOnError> => (options.client ?? client).get<GetTriggersResponses, GetTriggersErrors, ThrowOnError>({ url: '/projects/{name}/triggers', ...options });

/**
 * Append a trigger to the App manifest (the console "Add trigger" form)
 *
 * Adds a trigger to `nano.app.json`'s `triggers[]` from the console's Add-trigger dialog, so a maker wires a source without hand-editing the manifest. The server places the supplied `config` fields into the shape each source kind expects (core kinds read some keys at the trigger's top level, e.g. cron's `spec` and file's `path`; pack kinds read a nested `config`), validates the id is unique and the kind is recognised, writes the manifest, and returns the refreshed triggers + registry.
 *
 */
export const addTrigger = <ThrowOnError extends boolean = false>(options: Options<AddTriggerData, ThrowOnError>): RequestResult<AddTriggerResponses, AddTriggerErrors, ThrowOnError> => (options.client ?? client).post<AddTriggerResponses, AddTriggerErrors, ThrowOnError>({
    url: '/projects/{name}/triggers',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Enqueue a synthetic trigger event into the durable inbox
 *
 * The manual/synthetic source of ADR 0025 phase 1 (and the Triggers panel's "run now"): persists an event for a declared trigger into the App's durable inbox with a deterministic idempotency key, so the dispatcher applies its `action` to the engine exactly once per key. A repeat of the same idempotency key is a no-op (`enqueued=false`), proving the §3 dedup boundary.
 *
 */
export const enqueueTriggerEvent = <ThrowOnError extends boolean = false>(options: Options<EnqueueTriggerEventData, ThrowOnError>): RequestResult<EnqueueTriggerEventResponses, EnqueueTriggerEventErrors, ThrowOnError> => (options.client ?? client).post<EnqueueTriggerEventResponses, EnqueueTriggerEventErrors, ThrowOnError>({
    url: '/projects/{name}/triggers/enqueue',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Trigger inbox status (row counts by state + most recent rows)
 */
export const getTriggerInbox = <ThrowOnError extends boolean = false>(options: Options<GetTriggerInboxData, ThrowOnError>): RequestResult<GetTriggerInboxResponses, GetTriggerInboxErrors, ThrowOnError> => (options.client ?? client).get<GetTriggerInboxResponses, GetTriggerInboxErrors, ThrowOnError>({ url: '/projects/{name}/triggers/inbox', ...options });

/**
 * Enabled connectors + available connector registry (ADR 0050)
 *
 * Lists the App manifest's enabled connector workers (`workers[]` entries supplied by an installed pack, ADR 0050 — the outbound edge), each resolved against the connector registry: the union of every installed pack's declared `workers[]`. `backed` says whether the pack still ships a launchable worker for the type; `recognized` whether the type is in the registry at all. Also returns the full registry so the console can offer an "Add connector" picker, and any coherence errors (e.g. an enabled connector whose pack was uninstalled). This is the data the Connectors panel renders — the outbound mirror of `getTriggers`.
 *
 */
export const getConnectors = <ThrowOnError extends boolean = false>(options: Options<GetConnectorsData, ThrowOnError>): RequestResult<GetConnectorsResponses, GetConnectorsErrors, ThrowOnError> => (options.client ?? client).get<GetConnectorsResponses, GetConnectorsErrors, ThrowOnError>({ url: '/projects/{name}/connectors', ...options });

/**
 * Enable a connector into the App manifest (the console "Add connector" form)
 *
 * Enables a pack-supplied connector by appending a worker to `nano.app.json`'s `workers[]` (with `connector` naming the pack and `taskType` the job type — the design→runtime seam with the pack's element-template component, ADR 0050 §2). Optionally writes a named `connections[]` entry (env-pointer credentials, never inline secrets, ADR 0027 §5) referenced by the worker. Validates the type is a recognised connector and not already enabled, writes the manifest, and returns the refreshed connectors + registry. The outbound mirror of `addTrigger`.
 *
 */
export const addConnector = <ThrowOnError extends boolean = false>(options: Options<AddConnectorData, ThrowOnError>): RequestResult<AddConnectorResponses, AddConnectorErrors, ThrowOnError> => (options.client ?? client).post<AddConnectorResponses, AddConnectorErrors, ThrowOnError>({
    url: '/projects/{name}/connectors',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});
